#include "request_log.h"

#include <cstdio>
#include <string>

std::string format_request_log(const Request &req, double elapsed_ms)
{
    char buf[128];
    std::sprintf(buf, "%s %s -> %d (%.1f ms) user=%lld",
                 req.method.c_str(), req.path.c_str(), req.status,
                 elapsed_ms, req.user_id);
    return buf;
}

