#include "request_log.h"

#include <string>

#include <fmt/format.h>

std::string format_request_log(const Request &req, double elapsed_ms)
{
    return fmt::format("{} {} -> {} ({:.1f} ms) user={}",
                       req.method, req.path, req.status, elapsed_ms, req.user_id);
}

std::string format_request_log(std::string_view pattern, const Request &req, double elapsed_ms)
{
    return fmt::format(pattern,
                       fmt::arg("method", req.method), fmt::arg("path", req.path),
                       fmt::arg("status", req.status), fmt::arg("ms", elapsed_ms),
                       fmt::arg("user", req.user_id));
}

std::string format_request_log(std::string_view pattern, const Request &req, double elapsed_ms)
{
    try {
        return fmt::format(fmt::runtime(pattern),
                           fmt::arg("method", req.method), fmt::arg("path", req.path),
                           fmt::arg("status", req.status), fmt::arg("ms", elapsed_ms),
                           fmt::arg("user", req.user_id));
    } catch (const fmt::format_error &e) {
        return fmt::format("bad log pattern: {}", e.what());
    }
}
